mapper.select:
SELECT MONTH(op.operate_time) AS month, COUNT(DISTINCT st.storage_id) AS totalNum, COUNT(CASE WHEN ro.return_request = 0 THEN st.storage_id END) AS refundedNum, COUNT(CASE WHEN ro.return_request = 1 THEN st.storage_id END) AS repairedNum, COUNT(CASE WHEN ro.return_request = 2 THEN st.storage_id END) AS recycledNum FROM storage AS st LEFT JOIN operate AS op ON st.storage_id = op.storage_id LEFT JOIN return_order AS ro ON st.return_order_num = ro.return_order_num
AND op.operate_status = 0 AND YEAR(op.operate_time) = #{year}
GROUP BY MONTH(op.operate_time)
